# Generated by build.py from recipe.yml for recipe smtp-send-a-batch-of-mails-from-files. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'shop@example.com:shoppass', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "outbox/order-[101-103].eml" -w "%{response_code} %{num_connects}\n" smtp://127.0.0.1:8080/example.com --next -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/ } finally { Stop-Process $server0 }
